import type { ParsedExamRecord } from "./parseWorkbook";

function toReadableDate(value: string | null) {
  if (!value) return "chưa rõ ngày";

  const d = new Date(`${value}T00:00:00`);
  if (Number.isNaN(d.getTime())) return value;

  return d.toLocaleDateString("vi-VN");
}

export async function ensureNotificationPermission(): Promise<
  NotificationPermission | "unsupported"
> {
  if (typeof window === "undefined" || !("Notification" in window)) {
    return "unsupported";
  }

  if (window.Notification.permission === "granted") {
    return "granted";
  }

  if (window.Notification.permission === "denied") {
    return "denied";
  }

  return await window.Notification.requestPermission();
}

export function notifyNewExams(records: ParsedExamRecord[]) {
  if (typeof window === "undefined" || !("Notification" in window)) return;
  if (window.Notification.permission !== "granted") return;
  if (!records.length) return;

  const sample = records[0];

  const title =
    records.length === 1
      ? `Lịch thi mới: ${sample.courseCode || "Môn học"}`
      : `Có ${records.length} lịch thi mới`;

  const body =
    records.length === 1
      ? `${sample.courseName || sample.noticeTitle} • ${toReadableDate(
          sample.examDate
        )} • ${sample.startTime || "chưa rõ giờ"}`
      : `${records
          .slice(0, 3)
          .map((r) => r.courseCode || r.courseName || "Môn học")
          .join(", ")}${records.length > 3 ? "..." : ""}`;

  try {
    const notification = new window.Notification(title, {
      body,
      tag: "mydtu-exams-new",
    });

    notification.onclick = () => {
      window.focus();
      notification.close();
    };
  } catch {
    // ignore
  }
}